import{_ as h,C as l,c as d,o as k,j as e,G as i,ak as p,a}from"./chunks/framework.D7ejh1zC.js";const _=JSON.parse('{"title":"事件循环","description":"","frontmatter":{},"headers":[],"relativePath":"javascript/knowledge/事件循环.md","filePath":"concept/javascript/knowledge/事件循环.md","lastUpdated":1786880804000}'),c={name:"javascript/knowledge/事件循环.md"};function u(b,s,g,m,E,y){const t=l("mdInfo"),n=l("word"),r=l("NolebaseGitContributors"),o=l("NolebaseGitChangelog");return k(),d("div",null,[s[5]||(s[5]=e("h1",{id:"事件循环",tabindex:"-1"},[a("事件循环 "),e("a",{class:"header-anchor",href:"#事件循环","aria-label":'Permalink to "事件循环"'},"​")],-1)),i(t),e("p",null,[s[0]||(s[0]=a("讲 ",-1)),i(n,{text:"事件循环"}),s[1]||(s[1]=a("，先要了解前因后果：浏览器的 ",-1)),i(n,{text:"进程"}),s[2]||(s[2]=a(" 模型。事件循环跟浏览器密切相关，浏览器要执行 JS，与浏览器密切相关。了解浏览器，先讲浏览器进程模型。",-1))]),s[6]||(s[6]=p('<h2 id="浏览器进程模型" tabindex="-1">浏览器进程模型 <a class="header-anchor" href="#浏览器进程模型" aria-label="Permalink to &quot;浏览器进程模型&quot;">​</a></h2><h3 id="浏览器进程的概念" tabindex="-1">浏览器进程的概念 <a class="header-anchor" href="#浏览器进程的概念" aria-label="Permalink to &quot;浏览器进程的概念&quot;">​</a></h3><p>一个程序，像QQ，微信，王者荣耀，他们都属于程序，程序运行需要内存空间。程序的变量、对象、函数等，这些东西都是放到内存里边的，所以它需要有一块自己专属的内存空间，不够了，再扩容。</p><p>于是程序运行需要一块专属内存空间，可以把进程简单理解为就是这块内存空间，有这块内存空间就是进程，每个程序启动时至少有一个进程，即至少一块空间，而且进程与进程之间相互独立，内存空间之间隔离。</p><p>隔离的好处在于，如果QQ自己出了问题，内存空间乱了套，自己崩溃了，不会影响微信。因此进程之间相互隔离，每个应用至少有一个进程，进程之间相互独立，即使要通信，也需要双方同意。</p><h3 id="浏览器线程的概念" tabindex="-1">浏览器线程的概念 <a class="header-anchor" href="#浏览器线程的概念" aria-label="Permalink to &quot;浏览器线程的概念&quot;">​</a></h3><p>进程搞清楚后，接着看线程，两者密不可分。</p>',7)),e("p",null,[s[3]||(s[3]=a("运行代码的「人」，可简单称为 ",-1)),i(n,{text:"线程"}),s[4]||(s[4]=a("，一个进程至少有一个线程，否则分配内存空间，不干活就没用，就会杀死进程，进程退出叫杀死进程。所以，一个进程至少有一个线程去干活，去运行代码，因此在进程启动时，会自动创建一个线程来运行代码，这个线程称为主线程，即跟随进程启动产生的线程。",-1))]),s[7]||(s[7]=p(`<p>很多程序比较复杂，可能需要同时执行多块代码，比如王者荣耀，要监听各种操作，让人物跟随操作移动，还要网络通信，都需要网络，这么多事情，一个人忙不过来，于是主线程忙不过来时，会想办法多招人，启动更多线程执行代码。一个进程可以包含多个线程。</p><h3 id="浏览器的进程和线程" tabindex="-1">浏览器的进程和线程 <a class="header-anchor" href="#浏览器的进程和线程" aria-label="Permalink to &quot;浏览器的进程和线程&quot;">​</a></h3><p>浏览器是一个多进程多线程的应用程序，内部工作极其复杂，为了避免相互影响，减少连环崩溃几率，当启动浏览器后，它会自动启动多个进程。其中一个进程崩溃了，也不会影响到另外的进程。</p><p>主要分为三个进程：</p><ul><li><p>浏览器进程</p><p>主要负责界面显示、用户交互、子进程管理等。浏览器进程内部会启动多个线程处理不同的任务。</p></li><li><p>网络进程</p><p>负责加载网络资源。网络进程内部会启动多个线程来处理不同的网络任务</p></li><li><p>渲染进程</p><p>渲染进程启动后，会开启一个渲染主线程，主线程负责执行 HTML、CSS、JS 代码。默认情况下，浏览器会为每个标签页开启一个新的渲染进程，以保证不同的标签页之间不相互影响。</p></li></ul><blockquote><p>可以在浏览器的任务管理器查看当前所有进程。</p></blockquote><p>渲染主线程是浏览器最繁忙的线程，需要它处理的任务包括但不限于：</p><ul><li>解析 <code>HTML</code></li><li>解析 <code>CSS</code></li><li>计算样式</li><li>布局</li><li>处理图层</li><li>每秒把页面画60次（<code>FPS</code> 帧率）</li><li>执行全局 <code>JS</code> 代码</li><li>执行事件处理函数</li><li>......</li></ul><p>如果主线程遇到一个任务，该如何调度？</p><p>比如：</p><ul><li>在执行 JS 函数时，用户点击了一个按钮，应该立即执行这个点击函数吗？</li><li>在执行 JS 函数时，某个计时器时间到了，应该立即执行这个计时器函数吗？</li><li>在执行用户点击按钮时，某个计时器时间到了，应该先执行点击函数还是计时器函数？</li></ul><p>渲染主线程想出了一个新的方法：排队。主要做以下操作：</p><ol><li><p>在最开始的时候，渲染主线程会进入一个无限循环</p><p>渲染主线程的启动源码是用 C++ 写的：</p><div class="language-c++ vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c++</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( ;; ) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  Delegate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::NextWorkInfo next_work_info </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delegate-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DoWork</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ....</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>条件永远为真，就能进入无限循环。他每一次循环做了很多事情，如从消息队列里拿下一个任务。</p></li><li><p>每一次循环会检查消息队列中是否有任务存在。如果有，就取出第一个任务执行，执行完一个后进入下一次循环。如果没有，则进入休眠状态</p></li><li><p>其他所有线程（包括其他进程的线程）可以随时向消息队列添加任务，新任务会加到消息队列的末尾。在添加新任务时，如果主线程是休眠状态，则会将其唤醒继续循环拿去任务</p></li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>整个过程，被称之为事件循环，也被称之为消息循环。</p></div><h3 id="事件循环其他细节" tabindex="-1">事件循环其他细节 <a class="header-anchor" href="#事件循环其他细节" aria-label="Permalink to &quot;事件循环其他细节&quot;">​</a></h3><p>事件循环到此已经说明完毕了，但还是不够，事件循环里面的细节也需要解释一下，事件循环会有更多的理解。</p><h3 id="事件循环与异步" tabindex="-1">事件循环与异步 <a class="header-anchor" href="#事件循环与异步" aria-label="Permalink to &quot;事件循环与异步&quot;">​</a></h3><p>代码在执行过程中，会遇到一些 <em>无法立即处理的任务</em> ，比如：</p><ul><li>计时完成后需要执行的任务 —— <code>setTimeout</code> 、<code>setInterval</code></li><li>网络通信完成后需要执行的任务 —— <code>XHR</code> 、<code>Fetch</code></li><li>用户操作后需要执行的任务 —— <code>addEventListener</code></li></ul><p>如果让 <em>渲染主线程</em> 等待这些任务的时机达到，就会导致主线程长期处于 “阻塞” 的状态，从而导致浏览器 “卡死” 。</p><p>渲染主线程承担着极其重要的工作，无论如何不能阻塞！</p><p>因此，浏览器选择异步来解决这个问题。使用异步方式，<strong>渲染主线程永不阻塞</strong> 。</p><div class="note custom-block github-alert"><p class="custom-block-title">如何理解 JS 异步？</p><p></p><p>JS 是单线程语言，这是因为它运行在浏览器的渲染主线程中。而渲染主线程只有一个。</p><p>但是渲染主线程承担很大工作，如渲染页面、执行 JS 操作等，如果使用同步的方式，就有可能造成主线程阻塞，导致消息队列中很多任务无法得到执行。一方面导致繁忙的主线程白白消耗时间，另一方面导致页面无法及时更新，给用户造成卡死现象。</p><p>所以浏览器采用异步的方式来避免，具体做法是当某些任务发生时，比如定时器、事件监听等，主线程将任务交给其他线程执行处理，自身立即结束任务执行，转而执行后续代码。当其他线程完成后，将事先传递的回调函数包装成任务，加入到消息队列的末尾排队，等待主线程调度执行。</p></div><h3 id="事件循环中-js-阻碍渲染" tabindex="-1">事件循环中 JS 阻碍渲染 <a class="header-anchor" href="#事件循环中-js-阻碍渲染" aria-label="Permalink to &quot;事件循环中 JS 阻碍渲染&quot;">​</a></h3><p>因为 JS 和渲染线程都在浏览器的渲染主线传上，执行 JS 时，渲染只能等待，直到 JS 渲染完毕。因此如果 JS 代码执行时间过长，会有阻碍渲染的麻烦。</p><h3 id="事件循环任务优先级" tabindex="-1">事件循环任务优先级 <a class="header-anchor" href="#事件循环任务优先级" aria-label="Permalink to &quot;事件循环任务优先级&quot;">​</a></h3><p>任务没有优先级，在消息队列中先进先出。但是 <strong>消息队列是有优先级的</strong> 。</p><p>根据 W3C 最新解释：</p><ul><li>每个任务都有一个任务类型，同一个任务类型必须在一个队列，不同类型的任务可以分属于不同的队列。在一次事件中，浏览器可以根据实际情况从不同的队列中取出任务执行。</li><li>浏览器必须准备好一个微队列，微队列中的任务优先所有其他任务执行</li></ul><p>在目前 chrome 的实现中，至少包含下面的队列：</p><ul><li><p>延时队列：用于存放计时器，优先级 中</p></li><li><p>交互队列：用于存放用户交互后的函数，优先级 高</p></li><li><p>微队列：用于存放需要最快执行的任务，优先级 最高</p><blockquote><p>添加任务到微队列的主要方式为使用 <code>Promise</code> 、<code>MutationObserver</code></p></blockquote></li></ul><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">enum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> class TaskType: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unsigned</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  kUserInteraction</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 用户交互</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  kNetWorking</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 网络</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  kJavaScriptTimeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 定时器</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  kWebSocket</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>浏览器还有很多其他队列，但是和我们开发关系不大，不做考虑。</p><h3 id="事件循环总结" tabindex="-1">事件循环总结 <a class="header-anchor" href="#事件循环总结" aria-label="Permalink to &quot;事件循环总结&quot;">​</a></h3><p>浏览器的进程模型，描述浏览器在启动后，它会开启多个进程，原因是为了隔离，避免一个进程的功能运行崩溃了之后影响到其他进程。隔离之后，一个进程崩溃不会影响到别人。</p><p>其次重点讲了渲染进程，特别是渲染进程里的主线程叫做渲染主线程，因为渲染主线程承担的事情太多，因此，它找到了一种方式来解决事情混乱的问题，排队。</p><p>这些事情一件一件处理，不要同时处理几件，这样使用一个队列的方式，把一个任务一个任务取出来执行，执行完了之后再取下一个，这就是事件循环，实际上它本质上就是用了一个无限的循环，每一次循环取一个任务执行，执行完了取下一个，下一次循环取下一个。</p><p>这个事件循环其实跟异步就有关系，如果使用同步方式，就会造成阻塞，而用这种事件循环的方式，把任务加到队列里排队，就不会有阻塞问题</p><ul><li>事件循环是异步的实现方式</li><li>单线程是异步产生的原因</li></ul><p>有了异步之后，线程永不阻塞，在事件循环里边实际上使用了多个队列，有微队列，有延时队列，有交互队列，最先执行的一定是微队列，每一次取任务的时候，优先从微队列里面去取，取完了之后再去看其他队列。</p><p>在延时队列和交互队列这块，目前是交互队列优先，延时队列后执行，将来会怎么样不知道，但一定是微队列首先执行，它的优先级是最高的。</p>`,41)),i(r),i(o)])}const F=h(c,[["render",u]]);export{_ as __pageData,F as default};
